class Solution { public: int numOfArrays(int n,int m,int k){const long long mod=1000000007;vector<vector<long long>> dp(k+1,vector<long long>(m+1));for(int maximum=1;maximum<=m;++maximum)dp[1][maximum]=1;for(int length=2;length<=n;++length){vector<vector<long long>> next(k+1,vector<long long>(m+1));for(int cost=1;cost<=k;++cost)for(int maximum=1;maximum<=m;++maximum){next[cost][maximum]=(next[cost][maximum]+dp[cost][maximum]*maximum)%mod;if(cost<k)for(int newMax=maximum+1;newMax<=m;++newMax)next[cost+1][newMax]=(next[cost+1][newMax]+dp[cost][maximum])%mod;}dp=move(next);}long long answer=0;for(int maximum=1;maximum<=m;++maximum)answer=(answer+dp[k][maximum])%mod;return answer;} };
